    {'id': 'PSOYBUSDM', 'desc': 'Soybeans (World Bank monthly)', 'cat': 'grain', 'unit': 'USD/mt', 'etf': 'SOYB'},
]

def compute_change_pct(latest, prior):
    if latest is None or prior is None:
        return None
    if prior == 0:
        return None
    return round(((latest - prior) / prior) * 100.0, 2)

def classify_regime(category, change_30d, change_90d):
    ch30 = change_30d if change_30d is not None else 0.0
    ch90 = change_90d if change_90d is not None else 0.0
    if ch30 >= 10.0 and ch90 >= 20.0:
        return 'SURGING'
    if ch30 >= 5.0 or ch90 >= 15.0:
        return 'RISING'
    if ch30 <= -10.0 and ch90 <= -20.0:
        return 'COLLAPSING'
    if ch30 <= -5.0 or ch90 <= -15.0:
        return 'FALLING'
    return 'STEADY'

def thesis_for(cat, regime):
    if cat == 'oil':
        if regime == 'SURGING':
            return 'Oil supply shock - long USO/XLE/producers; airlines (AAL, DAL) at risk'
        if regime == 'COLLAPSING':
            return 'Demand destruction or glut - short energy, long airlines (LUV, SAVE)'
        if regime == 'RISING':
            return 'Oil rally continues - tactical USO/XLE long with tight stops'
    if cat == 'natgas':
        if regime == 'SURGING':
            return 'Nat-gas squeeze - long UNG; fertiliser input costs up (CF, NTR)'
        if regime == 'COLLAPSING':
            return 'Nat-gas glut - short UNG; LNG exporters (LNG, CQP) pressured'
    if cat == 'precious_metal':
        if regime == 'SURGING' or regime == 'RISING':
            return 'Gold bid - risk-off rotation; long GLD/GDX, miners (NEM, GOLD, AEM)'
        if regime == 'COLLAPSING' or regime == 'FALLING':
            return 'Gold weakness - risk-on rotation; rotate into cyclicals'
    if cat == 'industrial_metal':
        if regime == 'SURGING' or regime == 'RISING':
            return 'Global manufacturing expansion - long COPX, FCX, SCCO, BHP'
        if regime == 'COLLAPSING' or regime == 'FALLING':
            return 'Industrial demand weakening - recession-risk flag; trim cyclicals'
    if cat == 'grain':
        if regime == 'SURGING' or regime == 'RISING':
            return 'Grain squeeze - long CORN/WEAT/SOYB, agriculture (MOO, ADM, BG)'
        if regime == 'COLLAPSING' or regime == 'FALLING':
            return 'Grain surplus - short commodity ETFs, long ag-machinery (DE, AGCO) on input relief'
    return 'Monitor for divergence from historical range'

rows = []
for si in range(len(SERIES)):
    ent = SERIES[si]
