    desc = ent['desc']
    cat = ent['cat']
    unit = ent['unit']
    etf = ent['etf']
    try:
        resp = requests.get(
            BASE,
            params={
                'series_id': ser_id,
                'api_key': API_KEY,
                'file_type': 'json',
                'sort_order': 'desc',
                'limit': 120,
            },
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        obs = payload.get('observations', []) or []
    except Exception:
        continue
    values = []
    for oi in range(len(obs)):
        o = obs[oi]
        if not isinstance(o, dict):
            continue
        v = o.get('value', '.')
        if v == '.' or v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        values.append({'date': str(o.get('date', '') or ''), 'value': fv})
