        'description': desc,
        'category': cat,
        'unit': unit,
        'latest_value': round(latest, 4),
        'latest_date': latest_date,
        'value_30d_ago': round(v30, 4),
        'value_90d_ago': round(v90, 4),
        'change_30d_pct': ch30,
        'change_90d_pct': ch90,
        'regime_flag': regime,
        'investment_thesis': thesis,
        'etf_ticker': etf,
        '_epoch': now_epoch,
    })

if rows:
